'use strict';
/* How each question is topped up to 75 answers. A question lists where its candidates come from and how a
 * candidate is checked once its facts are fetched. Pools:
 *   taxon           the prompt's own reference lists (prompt.taxon + prompt.taxonFilter)
 *   groups + nameRe reference-list names (and existing creature entities) whose name matches nameRe
 *   corpus          every existing creature entity in the bank (checked with fb / nameRe)
 *   list            a hand list in tools/bank/lists/<name>.json (Wikipedia titles, "Title|Display name")
 * Checks:
 *   fb(f)           a predicate on the FishBase / SeaLifeBase page (species questions); a candidate with no page fails
 *   descRe / exRe   regexes on the Wikidata description + Wikipedia short description + first sentence (non-species)
 *   fish            only fish (Actinopterygii, Elasmobranchii, Holocephali, Sarcopterygii, Myxini, Petromyzonti)
 * `retire: true` marks a question that cannot honestly reach 75; `replace` entries are the new questions. */

const FISH_CLASSES = ['Actinopterygii', 'Elasmobranchii', 'Holocephali', 'Sarcopterygii', 'Myxini', 'Petromyzonti', 'Cephalaspidomorphi', 'Chondrichthyes', 'Teleostei'];
const ALL_ANIMAL_GROUPS = ['fish', 'freshwater-fish', 'sharks', 'rays', 'cephalopods', 'crustaceans', 'molluscs', 'nudibranchs', 'echinoderms', 'jellies', 'corals-anemones', 'deep-sea', 'cetaceans', 'pinnipeds', 'sea-reptiles', 'seabirds'];
const FISHY = ['fish', 'freshwater-fish', 'sharks', 'rays', 'deep-sea'];
const dist = (re) => (f) => !!(f && f.distribution && re.test(f.distribution));
const bio = (re) => Object.assign((f) => !!(f && f.biology && re.test(f.biology)), { _re: re });
const env = (re) => (f) => !!(f && f.environment && re.test(f.environment));
const uses = (re) => (f) => !!(f && f.uses && re.test(f.uses));
const threat = (...t) => (f) => !!(f && t.includes(f.threat));
const iucn = (...c) => (f) => !!(f && c.includes(f.iucnCode));
const any = (...ps) => (f) => ps.some(p => p(f));
const all = (...ps) => (f) => ps.every(p => p(f));
const PERSON = /\b(admiral|naval|navy|commander|officer|privateer|captain|explorer|navigator|oceanograph|diver|biolog|sailor|circumnavigat|naturalist|cartograph|filmmaker|photograph|pirate|buccaneer|corsair|seafarer|mariner|freediv|submarin|aquanaut|conservationist|author|writer|lord of the sea|fleet)/i;

